constexpr bool AnimLengthsSorted() {
    for (std::size_t i = 1; i < AnimLengths.size(); ++i) {
        if (AnimLengths[i - 1].id >= AnimLengths[i].id) {
            return false;
        }
    }
    return true;
}
static_assert(AnimLengthsSorted());

// The TAE length of animation `id` in seconds, or a negative value when it has none.
inline float AnimLengthSeconds(std::int32_t id) {
    const auto it = std::lower_bound(
        AnimLengths.begin(), AnimLengths.end(), id,
        [](const AnimLength& entry, std::int32_t value) { return entry.id < value; });
    return it != AnimLengths.end() && it->id == id ? it->seconds : -1.0f;
}

